const $=id=>document.getElementById(id),source=$('sourceCanvas'),overlay=$('overlay'),ctx=source.getContext('2d'),paintCanvas=document.createElement('canvas');paintCanvas.width=paintCanvas.height=512;const pctx=paintCanvas.getContext('2d'),octx=overlay.getContext('2d');
let original=null,loaded=false,busy=false,drawing=false,tool='paint',last=null,undo=[],token=null,references=[],currentJob=null,lastError=null,shared=false,sampleAvailable=true;
let targetRevision=0,maskRevision=0,referenceRevision=0;
const loading={photo:false,mask:false,references:false},uploading=()=>Object.values(loading).some(Boolean);
function beginTarget(){const revision=++targetRevision;maskRevision++;referenceRevision++;loading.photo=true;loading.mask=loading.references=false;original=null;loaded=false;drawing=false;last=null;references=[];undo=[];$('referenceFiles').value='';$('maskFile').value='';ctx.clearRect(0,0,512,512);pctx.clearRect(0,0,512,512);$('emptyInput').hidden=false;resetResult();renderReferences();renderMask();return revision;}

const isReference=()=>['reference','reference_select'].includes($('backbone').value);
const minimumReferences=()=>$('backbone').value==='reference_select'?1:3;
const notice=(message,error=false)=>{$('notice').textContent=message;$('notice').classList.toggle('error',error)};
const imageFrom=url=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(new Error('This image could not be opened. Try PNG or JPEG.'));im.src=url});
function maskPresent(){const a=pctx.getImageData(0,0,512,512).data;for(let i=3;i<a.length;i+=4)if(a[i]>127)return true;return false}
function controls(){ $('run').disabled=busy||uploading()||!loaded||!maskPresent()||(isReference()&&references.length<minimumReferences());$('undo').disabled=busy||uploading()||!undo.length;for(const id of ['imageFile','maskFile','framing','paint','erase','clear','backbone','mode','sample','referenceFiles','blend','detail','neutralize'])$(id).disabled=busy;$('sample').disabled=busy||!sampleAvailable; }
function renderMask(){octx.clearRect(0,0,512,512);if($('showMask').checked){octx.drawImage(paintCanvas,0,0);octx.globalCompositeOperation='source-in';octx.fillStyle='rgba(255,108,56,.48)';octx.fillRect(0,0,512,512);octx.globalCompositeOperation='source-over'}controls()}
function resetResult(){if(!busy){currentJob=null;lastError=null;}$('sizeComparison').hidden=true;$('sizeResults').replaceChildren();for(const id of ['download','downloadMask','downloadMetadata']){$(id).removeAttribute('href');$(id).classList.add('disabled');$(id).setAttribute('aria-disabled','true')}$('comparison').hidden=true;$('emptyResult').hidden=false;$('compare').disabled=true;$('resultBadge').textContent='Ready when you are'}
function snapshot(){undo.push(pctx.getImageData(0,0,512,512));if(undo.length>30)undo.shift()}
function frame(){if(!original)return;maskRevision++;loading.mask=false;ctx.fillStyle='#11171b';ctx.fillRect(0,0,512,512);ctx.drawImage(original,...InpaintingFraming.frameGeometry(original.naturalWidth,original.naturalHeight,$('framing').value));pctx.clearRect(0,0,512,512);undo=[];loaded=true;$('emptyInput').hidden=true;resetResult();renderMask()}
async function loadImage(file){
 if(busy)return;if(file.size>20*1024*1024)throw new Error('Please choose an image smaller than 20 MB.');
 const revision=beginTarget(),url=URL.createObjectURL(file);
 try{const image=await imageFrom(url);if(revision!==targetRevision)return;original=image;frame();$('sourceName').textContent=file.name;notice(isReference()?'New image loaded. Add matching reference photos for this person, then mark the damaged area.':'Paint over the area to reconstruct. You can adjust the framing first.');}
 catch(error){if(revision===targetRevision)throw error;}
 finally{URL.revokeObjectURL(url);if(revision===targetRevision){loading.photo=false;controls();}}
}
function applyMask(im){
 if(im.naturalWidth*im.naturalHeight>16000000)throw new Error('Use a mask below 16 megapixels, or a 512 × 512 mask matching the displayed frame.');
 const geometry=InpaintingFraming.maskGeometry(im.naturalWidth,im.naturalHeight,original.naturalWidth,original.naturalHeight,$('framing').value);
 const raw=document.createElement('canvas');raw.width=im.naturalWidth;raw.height=im.naturalHeight;const rawContext=raw.getContext('2d');rawContext.drawImage(im,0,0);
 const binary=InpaintingFraming.rasterizeMask(rawContext.getImageData(0,0,raw.width,raw.height).data,raw.width,raw.height,geometry);
 if(!binary.some(Boolean))throw new Error('The mask has no white pixels inside the displayed frame. Check its colours and image framing.');
 snapshot();const pixels=pctx.createImageData(512,512);for(let i=0;i<binary.length;i++){pixels.data[4*i]=pixels.data[4*i+1]=pixels.data[4*i+2]=255;pixels.data[4*i+3]=binary[i];}
 pctx.putImageData(pixels,0,0);resetResult();renderMask();
}
async function loadDemo(){
 if(busy)return;const reference=isReference(),revision=beginTarget();
 try{const response=await fetch('/api/demo'+(reference?'?reference=1':'')),data=await response.json();if(revision!==targetRevision)return;if(!response.ok)throw new Error(data.error);
  const [nextImage,nextMask]=await Promise.all([imageFrom(data.image),imageFrom(data.mask)]);if(revision!==targetRevision)return;
  references=(data.references||[]).map((data,index)=>({name:'Sample reference '+(index+1),data}));renderReferences();original=nextImage;$('framing').value='crop';frame();applyMask(nextMask);undo=[];$('sourceName').textContent='Synthetic occlusion sample';notice(reference?'Sample loaded with four matching reference photos. Click Reconstruct face.':'Sample loaded with the complete damage mask. Click Reconstruct face, then inspect the full restored image.');
 }catch(error){if(revision===targetRevision)throw error;}
 finally{if(revision===targetRevision){loading.photo=false;controls();}}
}
function point(event){const r=overlay.getBoundingClientRect();return {x:Math.max(0,Math.min(512,(event.clientX-r.left)/r.width*512)),y:Math.max(0,Math.min(512,(event.clientY-r.top)/r.height*512))}}
function stroke(a,b){pctx.globalCompositeOperation=tool==='erase'?'destination-out':'source-over';pctx.strokeStyle='#fff';pctx.fillStyle='#fff';pctx.lineCap=pctx.lineJoin='round';pctx.lineWidth=Number($('brush').value);pctx.beginPath();pctx.moveTo(a.x,a.y);pctx.lineTo(b.x,b.y);pctx.stroke();pctx.beginPath();pctx.arc(b.x,b.y,pctx.lineWidth/2,0,Math.PI*2);pctx.fill();pctx.globalCompositeOperation='source-over';renderMask()}
overlay.addEventListener('pointerdown',e=>{if(!loaded||busy||uploading())return;e.preventDefault();overlay.focus();overlay.setPointerCapture(e.pointerId);snapshot();resetResult();drawing=true;last=point(e);stroke(last,last)});overlay.addEventListener('pointermove',e=>{if(!drawing)return;const next=point(e);stroke(last,next);last=next});for(const type of ['pointerup','pointercancel','lostpointercapture'])overlay.addEventListener(type,()=>{drawing=false;last=null});
$('paint').onclick=()=>{tool='paint';$('paint').setAttribute('aria-pressed','true');$('erase').setAttribute('aria-pressed','false')};$('erase').onclick=()=>{tool='erase';$('paint').setAttribute('aria-pressed','false');$('erase').setAttribute('aria-pressed','true')};$('undo').onclick=()=>{if(undo.length&&!busy&&!uploading()){pctx.putImageData(undo.pop(),0,0);resetResult();renderMask()}};$('clear').onclick=()=>{if(busy||uploading())return;snapshot();pctx.clearRect(0,0,512,512);resetResult();renderMask()};overlay.onkeydown=e=>{if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();$('undo').click()}};$('brush').oninput=()=>$('brushValue').textContent=$('brush').value+' px';$('showMask').onchange=renderMask;$('framing').onchange=()=>{frame();notice('Framing updated. Paint a new mask for this frame.')};
$('imageFile').onchange=async e=>{try{if(e.target.files[0])await loadImage(e.target.files[0])}catch(error){notice(error.message,true)}finally{e.target.value=''}};
$('maskFile').onchange=async e=>{
 const target=targetRevision,revision=++maskRevision;let url;
 try{if(busy)return;if(!loaded||loading.photo)throw new Error('Upload a face before its mask.');const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw new Error('Use a mask smaller than 10 MB.');loading.mask=true;controls();url=URL.createObjectURL(file);const image=await imageFrom(url);if(target!==targetRevision||revision!==maskRevision)return;applyMask(image);notice('Mask loaded using the same framing as your photo.');}
 catch(error){if(target===targetRevision&&revision===maskRevision)notice(error.message,true);}
 finally{if(url)URL.revokeObjectURL(url);if(target===targetRevision&&revision===maskRevision){loading.mask=false;e.target.value='';controls();}}
};
const drop=$('dropzone');drop.addEventListener('dragover',e=>{e.preventDefault();if(!busy)drop.classList.add('dragging')});drop.addEventListener('dragleave',()=>drop.classList.remove('dragging'));drop.addEventListener('drop',async e=>{e.preventDefault();drop.classList.remove('dragging');try{if(e.dataTransfer.files[0])await loadImage(e.dataTransfer.files[0])}catch(error){notice(error.message,true)}});$('sample').onclick=()=>loadDemo().catch(e=>notice(e.message,true));
$('mode').onchange=()=>{resetResult();$('modeHint').textContent={expand:'Covers missed edges, but may also replace nearby valid pixels.',painted:'Replaces only the pixels inside your mask.',learned:'Keeps your painted area and may add nearby pixels. Experimental: it can replace valid detail; it is not a verified quality upgrade.'}[$('mode').value]};
function exportMask(){const c=document.createElement('canvas');c.width=c.height=512;const t=c.getContext('2d');t.fillStyle='black';t.fillRect(0,0,512,512);t.drawImage(paintCanvas,0,0);return c.toDataURL('image/png')}
function compare(){$('inputTag').hidden=Number($('compare').value)===100;$('comparisonLine').hidden=[0,100].includes(Number($('compare').value));$('afterImage').style.clipPath=`inset(0 ${100-Number($('compare').value)}% 0 0)`;$('comparisonLine').style.left=$('compare').value+'%'}$('compare').oninput=compare;
async function readJob(id){for(let attempt=0;attempt<12;attempt++){try{const response=await fetch('/api/jobs/'+id,{signal:AbortSignal.timeout(15000)});if(response.status>=500)throw new TypeError('Host temporarily unavailable');const data=await response.json();if(!response.ok){const error=new Error(data.error||'Could not read the run');error.fatal=true;throw error}return data}catch(error){if(error.fatal)throw error;if(attempt===11)throw new Error('Connection interrupted. The host may still be processing this run; check with the owner before starting another.');$('workingText').textContent='Reconnecting to your running reconstruction…';await new Promise(resolve=>setTimeout(resolve,2000))}}}
async function reconstruct(){if(uploading())throw new Error('Wait for the image, mask and references to finish loading.');if(busy)throw new Error('A run is already in progress.');if(!loaded||!maskPresent())throw new Error('Paint or upload a mask first.');if(isReference()&&references.length<minimumReferences())throw new Error('Add the required matching reference photos first.');busy=true;currentJob=null;lastError=null;resetResult();controls();$('working').hidden=false;$('workingText').textContent='Preparing your image…';notice(shared?'Processing on the host GPU. The first run includes model loading.':'Processing locally. The first run includes model loading.');try{const sessionResponse=await fetch('/api/session');if(!sessionResponse.ok)throw new Error('The local server is unavailable.');token=(await sessionResponse.json()).token;const response=await fetch('/api/inpaint',{method:'POST',headers:{'Content-Type':'application/json','X-Local-Token':token},body:JSON.stringify({image:source.toDataURL('image/png'),mask:exportMask(),backbone:$('backbone').value,mode:$('mode').value,blend:$('blend').checked?'poisson':'hard',detail:$('detail').value,neutralize:isReference()&&$('neutralize').checked,references:references.map(r=>r.data)})});const job=await response.json();if(!response.ok)throw new Error(job.error||'Could not start the run.');currentJob={id:job.id,status:'running'};let result;for(;;){await new Promise(resolve=>setTimeout(resolve,750));result=await readJob(job.id);currentJob=result;$('workingText').textContent=result.message;if(result.status==='error')throw new Error(result.message);if(result.status==='complete')break}await Promise.all([imageFrom(result.result),imageFrom(result.input)]);$('beforeImage').src=result.input;$('afterImage').src=result.result;$('comparison').hidden=false;$('emptyResult').hidden=true;$('compare').disabled=false;$('compare').value='100';compare();for(const [id,url] of [['download',result.result],['downloadMask',result.mask],['downloadMetadata',result.metadata]]){$(id).href=url;$(id).classList.remove('disabled');$(id).setAttribute('aria-disabled','false')}renderSizeComparison(result.comparisons||[]);$('resultBadge').textContent=`${result.resolution||256} × ${result.resolution||256} · PNG`;notice(`Restoration ready. Reconstruction took ${result.seconds.toFixed(2)} seconds after loading. ${result.selected_reference_count ? `Selected ${result.selected_reference_count} reference. ` : ""}${(result.warnings||[]).join(" ")} Drag the comparison slider to inspect the result.`);return {id:job.id,status:'complete',result:result.result}}catch(error){lastError=error.message;notice(error.message,true);throw error}finally{busy=false;$('working').hidden=true;controls()}}
$('run').onclick=()=>reconstruct().catch(e=>notice(e.message,true));
async function initialize(){const initialTarget=targetRevision;try{const response=await fetch('/api/session');const session=await response.json();if(!response.ok)throw new Error('The local server is unavailable.');token=session.token;shared=!!session.shared;sampleAvailable=session.sample_available!==false;if(sampleAvailable){if(targetRevision===initialTarget)await loadDemo()}else{$('sample').hidden=true;notice('Private research demo. Upload a photo and paint the area to reconstruct.');controls()}}catch(e){notice(e.message,true)}if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});for(const spec of [{name:'get_inpainting_state',title:'Read inpainting workspace',description:'Read whether an image and mask are ready and which local model is selected.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({imageLoaded:loaded,maskPresent:maskPresent(),busy,referenceCount:references.length,backbone:$('backbone').value,mode:$('mode').value,edgeBlending:$('blend').checked,detail:$('detail').value,job:currentJob,error:lastError})},{name:'run_local_inpainting',title:'Reconstruct the current face',description:'Start GPU reconstruction of the current image and mask. Returns immediately; read get_inpainting_state for progress and the completed result.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(input&&Object.keys(input).length)throw new Error('This tool accepts no parameters.');if(busy)throw new Error('A run is already in progress.');if(uploading())throw new Error('Wait for uploads to finish.');if(!loaded||!maskPresent())throw new Error('Paint or upload a mask first.');if(isReference()&&references.length<minimumReferences())throw new Error('Add the required matching reference photos first.');reconstruct().catch(()=>{});return {status:'started'}}}]){try{await document.modelContext.registerTool(spec,{signal:lifecycle.signal})}catch(error){console.warn('Optional WebMCP registration unavailable',error)}}}}

function renderReferences(){
  $('referenceList').replaceChildren();
  references.forEach((reference,index)=>{const item=document.createElement('div');item.className='reference-item';const image=document.createElement('img');image.src=reference.data;image.alt=`Reference photo ${index+1}`;const remove=document.createElement('button');remove.type='button';remove.textContent='×';remove.setAttribute('aria-label',`Remove reference ${index+1}`);remove.onclick=()=>{if(busy)return;referenceRevision++;loading.references=false;references.splice(index,1);resetResult();renderReferences()};item.append(image,remove);$('referenceList').append(item)});
  $('referenceCount').textContent=`${references.length} of 4 photos added`;controls();
}
$('backbone').onchange=()=>{resetResult();const model=$('backbone').value,reference=['reference','reference_select'].includes(model);$('referencePanel').hidden=!reference;if(!reference)$('detail').value='standard';$('referenceHelp').textContent=model==='reference_select'?'Add 1–4 different photos of the same person. The experimental scorer selects one usable photo. Invalid references are listed in the diagnostics.':'Use 3–4 different, clear photos of this same person, with one face per photo.';$('outputNote').textContent=model==='resshift'?'Output: 512 × 512 PNG (256 px model; visible detail preserved)':'Output: 512 × 512 PNG';$('modelHint').textContent={lama:'Best suited to small texture repairs. Missing eyes, mouths or large face regions can become blurry or distorted; use matching reference photos for those cases.',resshift:'A face-oriented diffusion baseline. Missing features are generated and may change the person’s appearance.',reference_select:'Experimental: accepts 1–4 photos and chooses one using the marked region and quality signals. Improvement is under evaluation. Diagnostics are available after the run.',reference:'Uses matching photos to guide appearance. Inspect the result: resemblance and missing details are not guaranteed.'}[model];$('mode').querySelector('[value=learned]').disabled=reference;if(reference&&$('mode').value==='learned'){$('mode').value='expand';$('mode').dispatchEvent(new Event('change'))}controls()};
$('referenceFiles').onchange=async event=>{
 if(busy)return;const files=[...event.target.files];if(!files.length)return;const target=targetRevision,revision=++referenceRevision;
 loading.references=true;resetResult();controls();
 try{if(!loaded||loading.photo)throw new Error('Choose the target image before its reference photos.');if(references.length+files.length>4)throw new Error('Use up to four reference photos. Remove one before adding another.');const added=[];
  for(const file of files){if(file.size>20*1024*1024)throw new Error('Each reference photo must be smaller than 20 MB.');const url=URL.createObjectURL(file);try{const image=await imageFrom(url);if(target!==targetRevision||revision!==referenceRevision)return;const canvas=document.createElement('canvas'),scale=Math.min(1,512/Math.max(image.naturalWidth,image.naturalHeight));canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);added.push({name:file.name,data:canvas.toDataURL('image/png')});}finally{URL.revokeObjectURL(url)}}
  if(target!==targetRevision||revision!==referenceRevision)return;references.push(...added);renderReferences();notice('Reference photos added. Mark the damaged input area, then reconstruct.');
 }catch(error){if(target===targetRevision&&revision===referenceRevision)notice(error.message,true);}
 finally{if(target===targetRevision&&revision===referenceRevision){loading.references=false;event.target.value='';controls();}}
};
for(const id of ['blend','detail','neutralize'])$(id).addEventListener('change',resetResult);
initialize();


function renderSizeComparison(items){
  const container=$('sizeResults');container.replaceChildren();$('sizeComparison').hidden=!items.length;
  for(const item of items){
    const card=document.createElement('article'),title=document.createElement('h3');title.textContent=item.processing_size+' px processing';card.append(title);
    if(item.status==='complete'){
      const img=document.createElement('img');img.src=item.result;img.alt='Reconstruction processed at '+item.processing_size+' pixels';card.append(img);
      const timing=document.createElement('p');timing.textContent=item.seconds.toFixed(2)+' seconds after model loading';card.append(timing);
      for(const [label,url] of [['Download image',item.result],['Run settings',item.metadata]]){const a=document.createElement('a');a.href=url;a.textContent=label;a.download='';card.append(a);}
    }else{const failure=document.createElement('p');failure.textContent='This size failed: '+item.message;card.append(failure);}
    container.append(card);
  }
}
